import {getProviderFor} from '@github-ui/models-byok/providers'
import {ProviderLogo} from '@github-ui/models-byok/providers/ProviderLogo'
import type {CustomKey} from '@github-ui/models-byok/types'
import {Stack} from '@primer/react'
import {clsx} from 'clsx'
import {useId} from 'react'

import styles from './ApiKeys.module.css'
import {EditCustomKeyButton} from './EditCustomKeyButton'
import {EmptyState} from './EmptyState'

export function ApiKeys({
  onRefresh,
  customKeys,
  publicKey,
}: {
  publicKey: string
  customKeys: CustomKey[]
  onRefresh?: () => void
}) {
  return customKeys.length > 0 ? (
    <>
      {customKeys.map(customKey => (
        <ApiKey key={customKey.id} publicKey={publicKey} customKey={customKey} onRefresh={onRefresh} />
      ))}
    </>
  ) : (
    <EmptyState onSuccess={onRefresh} publicKey={publicKey} />
  )
}

function ApiKey({customKey, publicKey, onRefresh}: {publicKey: string; customKey: CustomKey; onRefresh?: () => void}) {
  const id = useId()

  return (
    <Stack direction="horizontal" align="center" gap="condensed" className={clsx(styles.ApiKey, 'Box-row--hover-gray')}>
      <Stack.Item grow id={id}>
        <ApiKeyDisplay customKey={customKey} />
      </Stack.Item>
      <EditCustomKeyButton publicKey={publicKey} customKey={customKey} aria-describedby={id} onRefresh={onRefresh} />
    </Stack>
  )
}

function ApiKeyDisplay({customKey}: {customKey: CustomKey}) {
  return (
    <div className={styles.ApiKeyDisplay}>
      <ProviderLogo provider={customKey.provider} size="small" />
      <div data-area="name">{customKey.name}</div>
      <div data-area="meta">
        {getProviderFor(customKey.provider).name} &middot; {pluralize(customKey.totalModels, 'model', 'models')}
      </div>
    </div>
  )
}

function pluralize(count: number, singular: string, plural: string): string {
  return `${count} ${count === 1 ? singular : plural}`
}
